package com.hostelfind.service;
import com.hostelfind.dto.ItemRequest; import com.hostelfind.model.*; import com.hostelfind.repository.*; import org.springframework.http.HttpStatus; import org.springframework.stereotype.Service; import org.springframework.web.server.ResponseStatusException; import java.util.*;
@Service public class ItemService { private final ItemRepository items; private final UserRepository users; public ItemService(ItemRepository items,UserRepository users){this.items=items;this.users=users;} public List<Item> publicItems(String q,String category,ItemType type){return items.findByStatus(ItemStatus.OPEN).stream().filter(i->category==null||category.isBlank()||i.getCategory().equalsIgnoreCase(category)).filter(i->type==null||i.getType()==type).filter(i->q==null||q.isBlank()||String.join(" ",i.getTitle(),i.getDescription(),i.getLocation()).toLowerCase().contains(q.toLowerCase())).toList();} public Item one(Long id){return items.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Item not found"));} public ItemResponse publicView(Item i){boolean sensitive=List.of("Wallet","ID Cards","Electronics","Keys").contains(i.getCategory());String description=sensitive?"This sensitive item is held safely by the hostel office. Use the claim form to provide private ownership details.":i.getDescription();return new ItemResponse(i.getId(),i.getTitle(),description,i.getCategory(),i.getImageUrl(),i.getLocation(),i.getDate(),i.getType(),i.getStatus());} public Item create(ItemRequest r){Item i=new Item();copy(i,r);i.setStatus(ItemStatus.PENDING);return items.save(i);} public Item update(Long id,ItemRequest r){Item i=one(id);copy(i,r);if(r.status()!=null)i.setStatus(r.status());return items.save(i);} public void delete(Long id){items.delete(one(id));} private void copy(Item i,ItemRequest r){i.setTitle(r.title());i.setDescription(r.description());i.setCategory(r.category());i.setImageUrl(r.imageUrl());i.setLocation(r.location());i.setDate(r.date());i.setType(r.type());i.setUser(users.findById(r.userId()).orElseThrow(()->new ResponseStatusException(HttpStatus.BAD_REQUEST,"Invalid userId")));} }
